import{_ as n,o as e,c as s,a2 as p}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"数据库连接1","description":"","frontmatter":{"title":"数据库连接1"},"headers":[],"relativePath":"ops-knowledge-base/cloud-native/cloud-db-mysql-plus/database-connection-1.md","filePath":"ops-knowledge-base/cloud-native/cloud-db-mysql-plus/database-connection-1.md","lastUpdated":1788259091000}'),l={name:"ops-knowledge-base/cloud-native/cloud-db-mysql-plus/database-connection-1.md"};function t(i,a,o,c,r,d){return e(),s("div",null,[...a[0]||(a[0]=[p(`<h2 id="_1-设置-ip-白名单后-是立即生效吗" tabindex="-1">1.设置 IP 白名单后，是立即生效吗？ <a class="header-anchor" href="#_1-设置-ip-白名单后-是立即生效吗" aria-label="Permalink to &quot;1.设置 IP 白名单后，是立即生效吗？&quot;">​</a></h2><p>不是。 IP 白名单设置后，需等待几分钟才生效。</p><p>若久未生效，请提工单反馈联系技术支持排查。</p><h2 id="_2-申请外网地址后-需要配置安全组吗" tabindex="-1">2.申请外网地址后，需要配置安全组吗？ <a class="header-anchor" href="#_2-申请外网地址后-需要配置安全组吗" aria-label="Permalink to &quot;2.申请外网地址后，需要配置安全组吗？&quot;">​</a></h2><p>不需要。</p><p>为确保外网访问的安全，MySQL Plus 外网安全组由系统维护。系统将根据外网端口自行放行安全组规则，用户无需另行配置和管理。</p><ul><li>申请外网地址时，集群将自动绑定一个外网安全组，并且系统会根据外网端口（默认3306）自动放行安全组规则，无需另行配置。</li><li>若外网端口或 IP 白名单被修改，集群关联的外网安全组将自动更新安全组规则，无需另行管理。</li></ul><h2 id="_3-支持跨区域访问数据库吗" tabindex="-1">3.支持跨区域访问数据库吗？ <a class="header-anchor" href="#_3-支持跨区域访问数据库吗" aria-label="Permalink to &quot;3.支持跨区域访问数据库吗？&quot;">​</a></h2><ul><li>内网访问：不支持跨区域问数据库。跨区域的云资源之间内网互不相通，需打通网络连接。</li><li>外网访问：申请外网地址后，您可以在 IP 白名单中添加跨区域云服务器公网 IP 地址，使用外网地址实现跨区域访问。</li></ul><h2 id="_4-如何定位本地设备的公网-ip-地址" tabindex="-1">4.如何定位本地设备的公网 IP 地址? <a class="header-anchor" href="#_4-如何定位本地设备的公网-ip-地址" aria-label="Permalink to &quot;4.如何定位本地设备的公网 IP 地址?&quot;">​</a></h2><p>为避免因配置的 IP 白名单有误，导致无法访问数据库。本小节介绍几种获取本地设备公网 IP 的方式。</p><ul><li><p>通过浏览器查询</p><p>可在浏览器输入以下任意一个地址，即可查询本地公网 IP 地址。</p><p><a href="https://www.cip.cc/" target="_blank" rel="noreferrer">https://www.cip.cc/</a></p><p><a href="https://www.ipip.net/" target="_blank" rel="noreferrer">https://www.ipip.net/</a></p></li><li><p>通过命令行查询</p><p>执行以下任意一个命令，即可获取本地公网 IP 地址。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> # UNIX/Linux</span></span>
<span class="line"><span> $ curl httpbin.org/ip</span></span>
<span class="line"><span> $ curl cip.cc</span></span>
<span class="line"><span> $ curl ifconfig.io</span></span>
<span class="line"><span> $ curl myip.ipip.net</span></span>
<span class="line"><span></span></span>
<span class="line"><span> # Windows</span></span>
<span class="line"><span> &gt;telnet cip.cc</span></span>
<span class="line"><span> &gt;ftp cip.cc</span></span></code></pre></div></li></ul><h2 id="_5-为何添加账户后-无法通过-proxy-节点访问" tabindex="-1">5.为何添加账户后，无法通过 Proxy 节点访问？ <a class="header-anchor" href="#_5-为何添加账户后-无法通过-proxy-节点访问" aria-label="Permalink to &quot;5.为何添加账户后，无法通过 Proxy 节点访问？&quot;">​</a></h2><p>在有 Proxy 情况下，添加账户后 Proxy 节点是无法感知的，需要重启 Proxy 节点才能感知到新创建的账户。</p>`,14)])])}const _=n(l,[["render",t]]);export{u as __pageData,_ as default};
